import sys
import os
import json
import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Any

def parse_date(date_str: str) -> Optional[datetime.date]:
    """Parse date from MM/DD/YYYY format."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        month, day, year = map(int, date_str.split('/'))
        return datetime.date(year, month, day)
    except (ValueError, AttributeError):
        return None

def read_data_file(file_path: Path) -> List[Dict[str, str]]:
    """Read a data file with '|' delimiter and return list of dicts."""
    data = []
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find header line (first non-comment line)
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split('|')
            break

    if not header:
        return data

    # Process data lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip().split('|') == header:
            continue  # Skip header line itself

        values = line.strip().split('|')
        # Pad with empty strings if needed
        while len(values) < len(header):
            values.append('')
        row = dict(zip(header, values))
        data.append(row)

    return data

def get_value_for_entity(data: List[Dict[str, str]], entity_id: str, 
                         value_field: str, entity_field: str = "WORKER_FILE_NUMBER") -> Optional[str]:
    """Get value for a specific entity from data."""
    for row in data:
        if row.get(entity_field) == entity_id:
            value = row.get(value_field, '').strip()
            if value:  # Only return non-empty values
                return value
    return None

def get_all_values_for_entity(data: List[Dict[str, str]], entity_id: str,
                              value_field: str, entity_field: str = "WORKER_FILE_NUMBER") -> List[str]:
    """Get all values for a specific entity from data (for conflict detection)."""
    values = []
    for row in data:
        if row.get(entity_field) == entity_id:
            value = row.get(value_field, '').strip()
            if value:
                values.append(value)
    return values

def resolve_fact(entity_id: str, primary_doc: str, primary_field: str,
                  fallback_doc: Optional[str], fallback_field: Optional[str],
                  data_dict: Dict[str, List[Dict[str, str]]]) -> Tuple[Any, str]:
    """
    Resolve a fact according to decision rules.
    Returns (value, document) or "ABSENT" or "CONFLICT"
    """
    # Get primary document data
    primary_data = data_dict.get(primary_doc, [])

    # Check for conflicts in primary document
    primary_values = get_all_values_for_entity(primary_data, entity_id, primary_field)

    if len(primary_values) == 0:
        # No value in primary document, try fallback if available
        if fallback_doc and fallback_field:
            fallback_data = data_dict.get(fallback_doc, [])
            fallback_values = get_all_values_for_entity(fallback_data, entity_id, fallback_field)

            if len(fallback_values) == 0:
                return "ABSENT", ""
            elif len(fallback_values) == 1:
                return [fallback_values[0], fallback_doc]
            else:
                # Check if all fallback values are the same
                if all(v == fallback_values[0] for v in fallback_values):
                    return [fallback_values[0], fallback_doc]
                else:
                    return "CONFLICT", ""
        else:
            return "ABSENT", ""
    elif len(primary_values) == 1:
        return [primary_values[0], primary_doc]
    else:
        # Multiple values in primary document
        # Check if they all agree
        if all(v == primary_values[0] for v in primary_values):
            return [primary_values[0], primary_doc]
        else:
            return "CONFLICT", ""

def main(directory_path: str):
    # Load all data files
    data_files = {
        'dol_receipts': 'dol_receipts.txt',
        'ead_cards': 'ead_cards.txt',
        'hr_roster': 'hr_roster.txt',
        'lca_filings': 'lca_filings.txt',
        'lca_notices': 'lca_notices.txt',
        'reverifications': 'reverifications.txt',
        'work_authorizations': 'work_authorizations.txt'
    }

    data_dict = {}
    for key, filename in data_files.items():
        file_path = Path(directory_path) / filename
        if file_path.exists():
            data_dict[key] = read_data_file(file_path)
        else:
            data_dict[key] = []

    # Define decision rules
    rules = {
        'wf.reverify_window': {
            'authorization expiry': {
                'primary': ('work_authorizations', 'EMPLOYABILITY_EVIDENCE_LAPSE'),
                'fallback': ('ead_cards', 'I766_VALID_TO')
            },
            'reverification date': {
                'primary': ('reverifications', 'SUPPLEMENT_B_EXECUTED'),
                'fallback': None
            }
        },
        'wf.notice_posting': {
            'notice posted': {
                'primary': ('lca_notices', 'NOTICE_DISPLAY_BEGIN'),
                'fallback': None
            },
            'notice removed': {
                'primary': ('lca_notices', 'NOTICE_DISPLAY_END'),
                'fallback': None
            },
            'LCA filed': {
                'primary': ('lca_filings', 'ETA9035_SUBMISSION_DAY'),
                'fallback': ('dol_receipts', 'OFLC_INTAKE_DAY')
            }
        }
    }

    # Process all pairs
    result = {}
    entity_ids = [f"E-401{i:02d}" for i in range(1, 17)]

    for rule_name in ['wf.reverify_window', 'wf.notice_posting']:
        for entity_id in entity_ids:
            pair_id = f"{rule_name}::{entity_id}"
            rule_facts = {}

            for fact_name, fact_config in rules[rule_name].items():
                primary_doc, primary_field = fact_config['primary']
                fallback = fact_config['fallback']
                fallback_doc, fallback_field = fallback if fallback else (None, None)

                value = resolve_fact(entity_id, primary_doc, primary_field,
                                     fallback_doc, fallback_field, data_dict)

                if value == "ABSENT":
                    rule_facts[fact_name] = "ABSENT"
                elif value == "CONFLICT":
                    rule_facts[fact_name] = "CONFLICT"
                else:
                    # value is a list [actual_value, document]
                    rule_facts[fact_name] = value

            result[pair_id] = rule_facts

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    main(sys.argv[1])
