    datetime(2027, 11, 11).date(),
    datetime(2027, 11, 25).date(),
    datetime(2027, 12, 24).date(), # Observed (Christmas is Saturday)
}

def parse_date(date_str: str) -> Optional[datetime.date]:
    """Parse date strings like 'Wed., March 11, 2026' or 'Mon., Feb. 7, 2026'."""
    if not date_str or "left blank" in date_str:
        return None
    # Remove day of week and period
    date_str = re.sub(r"^[A-Za-z]+\.\s*,\s*", "", date_str)
    # Standardize month abbreviations
    month_map = {
        "Jan.": "January", "Feb.": "February", "March": "March", "April": "April",
        "May": "May", "June": "June", "July": "July", "Aug.": "August",
        "Sept.": "September", "Oct.": "October", "Nov.": "November", "Dec.": "December",
    }
    for abbr, full in month_map.items():
        date_str = date_str.replace(abbr, full)
    try:
        return datetime.strptime(date_str, "%B %d, %Y").date()
    except ValueError:
        # Try without day suffix if present (like 1st, 2nd)
        date_str = re.sub(r"(\d+)(st|nd|rd|th)", r"\1", date_str)
        try:
            return datetime.strptime(date_str, "%B %d, %Y").date()
        except ValueError:
            return None

def is_business_day(date: datetime.date, holidays: set) -> bool:
    """Check if a date is a business day (Monday-Friday, not a holiday)."""
    return date.weekday() < 5 and date not in holidays

def add_business_days(start_date: datetime.date, days: int, holidays: set) -> datetime.date:
    """Add business days excluding weekends and holidays."""
    current = start_date
    added = 0
    while added < days:
        current += timedelta(days=1)
        if is_business_day(current, holidays):
            added += 1
    return current

def parse_html_file(file_path: Path) -> Dict[str, Dict[str, Optional[datetime.date]]]:
    """Parse an HTML file and extract records by staff badge."""
    data = {}
    try:
        content = file_path.read_text(encoding='utf-8')
    except Exception:
        return data

    # Find all article sheets
    articles = re.findall(r'<article[^>]*>.*?</article>', content, re.DOTALL)
    for article in articles:
        # Extract staff badge
        badge_match = re.search(r'<strong>(E-\d+)</strong>', article)
        if not badge_match:
            continue
        badge = badge_match.group(1)

        # Extract all field rows
        rows = re.findall(r'<tr>.*?</tr>', article, re.DOTALL)
        record = {}
        for row in rows:
            th_match = re.search(r'<th[^>]*>(.*?)</th>', row, re.DOTALL)
            td_match = re.search(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
            if th_match and td_match:
                field_name = re.sub(r'<[^>]+>', '', th_match.group(1)).strip()
                field_value = re.sub(r'<[^>]+>', '', td_match.group(1)).strip()
                # Skip void entries
                if "left blank" in field_value:
                    continue
                # Parse date if it looks like one
                date_val = parse_date(field_value)
                if date_val:
                    record[field_name] = date_val
                else:
                    # Keep as string for non-date fields
                    record[field_name] = field_value
        if record:
            data[badge] = record
    return data

def get_fact_value(
    badge: str,
    fact_name: str,
    rule_id: str,
    documents: Dict[str, Dict[str, Dict[str, Dict[str, Union[datetime.date, str]]]]]
) -> Union[List[Union[str, str]], str]:
    """Get value for a fact according to decision rules."""
    fact_defs = FACT_TO_DOC[rule_id][fact_name]
    for doc_name, field_name in fact_defs:
        if badge in documents.get(doc_name, {}):
            record = documents[doc_name][badge]
            if field_name in record:
                value = record[field_name]
                if isinstance(value, datetime.date):
                    return [value.isoformat(), doc_name]
                else:
                    return [str(value), doc_name]
    return "ABSENT"

def check_conflict(
    badge: str,
    fact_name: str,
    rule_id: str,
    documents: Dict[str, Dict[str, Dict[str, Dict[str, Union[datetime.date, str]]]]]
) -> bool:
    """Check if there are conflicting values in the deciding document."""
    fact_defs = FACT_TO_DOC[rule_id][fact_name]
    values = set()
    for doc_name, field_name in fact_defs:
        if badge in documents.get(doc_name, {}):
            record = documents[doc_name][badge]
            if field_name in record:
                value = record[field_name]
                if isinstance(value, datetime.date):
                    values.add(value.isoformat())
                else:
                    values.add(str(value))
    return len(values) > 1

def main(directory_path: str):
    # Load all documents
    documents = {}
    for file_name in [
        "dol_receipts.html",
        "ead_cards.html",
        "hr_roster.html",
        "lca_filings.html",
        "lca_notices.html",
        "reverifications.html",
        "work_authorizations.html",
    ]:
        file_path = Path(directory_path) / file_name
        doc_name = file_name.replace(".html", "")
        if file_path.exists():
            documents[doc_name] = parse_html_file(file_path)
        else:
            documents[doc_name] = {}

    # Prepare result structure
    result = {}

    # Process all pairs
    pairs = [
        f"wf.reverify_window::{badge}" for badge in [f"E-401{i:02d}" for i in range(1, 17)]
    ] + [
        f"wf.notice_posting::{badge}" for badge in [f"E-401{i:02d}" for i in range(1, 17)]
    ]

    for pair_id in pairs:
        rule_id, badge = pair_id.split("::")
        fact_result = {}

        for fact_name in FACT_TO_DOC[rule_id].keys():
            # Check for conflicts first
            if check_conflict(badge, fact_name, rule_id, documents):
                fact_result[fact_name] = "CONFLICT"
            else:
                fact_result[fact_name] = get_fact_value(badge, fact_name, rule_id, documents)

        result[pair_id] = fact_result

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)
    main(sys.argv[1])
