import sys
import os
import json
import re
from datetime import datetime, timedelta
from html.parser import HTMLParser
from collections import defaultdict

class SheetParser(HTMLParser):
    """Parse a single sheet (article) from the HTML."""
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_label = None
        self.data = {}
        self.current_text = ""
        self.in_void = False

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            for attr, val in attrs:
                if attr == "class" and "fields" in val:
                    self.in_table = True
        elif self.in_table and tag == "th":
            self.in_th = True
            self.current_text = ""
        elif self.in_table and tag == "td":
            self.in_td = True
            self.current_text = ""
            for attr, val in attrs:
                if attr == "class" and "void" in val:
                    self.in_void = True
        elif tag == "strong":
            self.current_text += "<strong>"
        elif tag == "em":
            self.current_text += "<em>"

    def handle_endtag(self, tag):
        if tag == "table":
            self.in_table = False
        elif tag == "th":
            self.in_th = False
            if self.current_text:
                self.current_label = self.current_text.strip()
        elif tag == "td":
            self.in_td = False
            if self.current_label and self.current_text:
                value = self.current_text.strip()
                if self.in_void:
                    value = None
                    self.in_void = False
                self.data[self.current_label] = value
                self.current_label = None
            self.current_text = ""
        elif tag == "strong":
            self.current_text += "</strong>"
        elif tag == "em":
            self.current_text += "</em>"

    def handle_data(self, data):
        if self.in_th or self.in_td:
            self.current_text += data

def parse_html_file(filepath):
    """Parse an HTML file and return a dict mapping staff badge to sheet data."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by article sheets
    articles = re.findall(r'<article class="sheet"[^>]*>.*?</article>', content, re.DOTALL)
    badge_to_data = {}

    for article in articles:
        parser = SheetParser()
        parser.feed(article)
        data = parser.data
        if "Staff badge" in data and data["Staff badge"]:
            badge = data["Staff badge"]
            # Remove HTML tags from badge if any
            badge = re.sub(r'<[^>]+>', '', badge).strip()
            badge_to_data[badge] = data

    return badge_to_data

def parse_date(date_str):
    """Parse date strings like 'Fri., June 12, 2026' to YYYY-MM-DD."""
    if not date_str:
        return None
    # Remove day of week and period
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    # Handle abbreviated months
    month_abbr = {
        'Jan.': 'January', 'Feb.': 'February', 'Mar.': 'March', 'Apr.': 'April',
        'May': 'May', 'Jun.': 'June', 'Jul.': 'July', 'Aug.': 'August',
        'Sep.': 'September', 'Sept.': 'September', 'Oct.': 'October',
        'Nov.': 'November', 'Dec.': 'December'
    }
    for abbr, full in month_abbr.items():
        if date_str.startswith(abbr):
            date_str = date_str.replace(abbr, full, 1)
            break
    try:
        dt = datetime.strptime(date_str.strip(), '%B %d, %Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        # Try alternative format
        try:
            dt = datetime.strptime(date_str.strip(), '%b %d, %Y')
            return dt.strftime('%Y-%m-%d')
        except:
            return None

def extract_fact(badge, fact_name, documents, fallback=None):
    """
    Extract a fact for a given badge according to decision rules.
    Returns one of:
      ["<value>", "<document>"]
      "ABSENT"
      "CONFLICT"
    """
    # Determine which documents to check and in what order
    doc_order = []
    if isinstance(documents, list):
        doc_order = documents
    elif isinstance(documents, str):
        doc_order = [documents]

    values_found = []
    source_docs = []

    for doc_name in doc_order:
        if badge in documents_data[doc_name]:
            data = documents_data[doc_name][badge]
            # Map fact name to field label in the document
            field_map = {
                'work_authorizations': {
                    'authorization expiry': 'Evidence expires'
                },
                'ead_cards': {
                    'authorization expiry': 'EAD valid to'
                },
                'reverifications': {
                    'reverification date': 'Supplement B signed on'
                },
                'lca_notices': {
                    'notice posted': 'Notice first displayed',
                    'notice removed': 'Notice withdrawn from display'
                },
                'lca_filings': {
                    'LCA filed': 'Submitted through FLAG'
                },
                'dol_receipts': {
                    'LCA filed': 'Agency receipt notice dated'
                }
            }

            if doc_name in field_map and fact_name in field_map[doc_name]:
                field_label = field_map[doc_name][fact_name]
                if field_label in data and data[field_label] is not None:
                    # Parse date if it's a date field
                    if 'date' in fact_name or 'expiry' in fact_name or 'posted' in fact_name or 'removed' in fact_name or 'filed' in fact_name:
                        date_val = parse_date(data[field_label])
                        if date_val:
                            values_found.append(date_val)
                            source_docs.append(doc_name)
                    else:
                        values_found.append(data[field_label])
                        source_docs.append(doc_name)

    # Check for conflicts
    if len(set(values_found)) > 1:
        return "CONFLICT"

    if values_found:
        return [values_found[0], source_docs[0]]

    # Try fallback if specified
    if fallback and badge in documents_data[fallback]:
        data = documents_data[fallback][badge]
        field_map = {
            'work_authorizations': {
                'authorization expiry': 'Evidence expires'
            },
            'ead_cards': {
                'authorization expiry': 'EAD valid to'
            },
            'lca_filings': {
                'LCA filed': 'Submitted through FLAG'
            },
            'dol_receipts': {
                'LCA filed': 'Agency receipt notice dated'
            }
        }

        if fallback in field_map and fact_name in field_map[fallback]:
            field_label = field_map[fallback][fact_name]
            if field_label in data and data[field_label] is not None:
                if 'date' in fact_name or 'expiry' in fact_name or 'filed' in fact_name:
                    date_val = parse_date(data[field_label])
                    if date_val:
                        return [date_val, fallback]
                else:
                    return [data[field_label], fallback]

    return "ABSENT"

def main(directory_path):
    global documents_data
    documents_data = {}

    # Define the files we need to parse
    files_to_parse = {
        'work_authorizations': 'work_authorizations.html',
        'ead_cards': 'ead_cards.html',
        'reverifications': 'reverifications.html',
        'lca_notices': 'lca_notices.html',
        'lca_filings': 'lca_filings.html',
        'dol_receipts': 'dol_receipts.html'
    }

    # Parse all documents
    for doc_name, filename in files_to_parse.items():
        filepath = os.path.join(directory_path, filename)
        if os.path.exists(filepath):
            documents_data[doc_name] = parse_html_file(filepath)
        else:
            print(f"Warning: File {filename} not found in {directory_path}", file=sys.stderr)
            documents_data[doc_name] = {}

    # Generate pairs
    badges = [f"E-402{i:02d}" for i in range(1, 17)]
    pairs = {}

    # wf.reverify_window pairs
    for badge in badges:
        pair_id = f"wf.reverify_window::{badge}"
        facts = {}

        # Fact: authorization expiry
        auth_expiry = extract_fact(badge, 'authorization expiry', 
                                   ['work_authorizations'], 
                                   fallback='ead_cards')
        facts['authorization expiry'] = auth_expiry

        # Fact: reverification date
        reverify_date = extract_fact(badge, 'reverification date', 
                                     ['reverifications'])
        facts['reverification date'] = reverify_date

        pairs[pair_id] = facts

    # wf.notice_posting pairs
    for badge in badges:
        pair_id = f"wf.notice_posting::{badge}"
        facts = {}

        # Fact: notice posted
        notice_posted = extract_fact(badge, 'notice posted', 
                                     ['lca_notices'])
        facts['notice posted'] = notice_posted

        # Fact: notice removed
        notice_removed = extract_fact(badge, 'notice removed', 
                                      ['lca_notices'])
        facts['notice removed'] = notice_removed

        # Fact: LCA filed
        lca_filed = extract_fact(badge, 'LCA filed', 
                                 ['lca_filings'], 
                                 fallback='dol_receipts')
        facts['LCA filed'] = lca_filed

        pairs[pair_id] = facts

    # Output as JSON
    print(json.dumps(pairs, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    main(sys.argv[1])
