def parse_sql_file(file_path):
    """Parse SQL file to extract table data."""
    data = []
    with open(file_path, 'r') as f:
        content = f.read()

    # Find INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*\(([^)]+)\)'
    # More robust pattern to handle multi-line VALUES
    lines = content.split('\n')
    in_insert = False
    current_values = []

    for line in lines:
        line = line.strip()
        if line.upper().startswith('INSERT INTO'):
            in_insert = True
            # Extract column names if needed
            if '(' in line and ')' in line:
                # Get everything after VALUES
                values_part = line.split('VALUES', 1)[-1].strip()
                if values_part.startswith('('):
                    current_values.append(values_part)
        elif in_insert and line:
            current_values.append(line)
            if line.endswith(');'):
                # Join and parse
                values_block = ' '.join(current_values)
                # Remove trailing );
                values_block = values_block.rstrip(');')
                # Parse individual value tuples
                tuples = []
                current_tuple = []
                depth = 0
                for char in values_block:
                    if char == '(':
                        depth += 1
                        if depth == 1:
                            continue
                    elif char == ')':
                        depth -= 1
                        if depth == 0:
                            # End of tuple
                            tuple_str = ''.join(current_tuple)
                            tuples.append(tuple_str)
                            current_tuple = []
                            continue
                    if depth >= 1:
                        current_tuple.append(char)

                for tuple_str in tuples:
                    # Split by comma, handling NULL and strings
                    parts = []
                    current_part = []
                    in_string = False
                    for char in tuple_str:
                        if char == "'":
                            in_string = not in_string
                            current_part.append(char)
                        elif char == ',' and not in_string:
                            parts.append(''.join(current_part).strip())
                            current_part = []
                        else:
                            current_part.append(char)
                    if current_part:
                        parts.append(''.join(current_part).strip())

                    # Clean parts
                    cleaned_parts = []
                    for part in parts:
                        if part.upper() == 'NULL':
                            cleaned_parts.append(None)
                        elif part.startswith("'") and part.endswith("'"):
                            cleaned_parts.append(part[1:-1])
                        else:
                            # Try to convert to int
                            try:
                                cleaned_parts.append(int(part))
                            except:
                                cleaned_parts.append(part)

                    data.append(cleaned_parts)

                current_values = []
                in_insert = False
        elif in_insert and not line:
            continue

    return data

def parse_table_structure(file_path):
    """Parse CREATE TABLE to understand column order."""
    with open(file_path, 'r') as f:
        content = f.read()

    # Find CREATE TABLE statement
    create_match = re.search(r'CREATE TABLE (\w+) \((.*?)\);', content, re.DOTALL)
    if not create_match:
        return None

    table_name = create_match.group(1)
    columns_section = create_match.group(2)

    # Parse column definitions
    columns = []
    lines = columns_section.split('\n')
    for line in lines:
        line = line.strip().strip(',')
        if line and not line.upper().startswith('PRIMARY KEY') and not line.upper().startswith('FOREIGN KEY'):
            # Extract column name (first word)
            col_name = line.split()[0]
            columns.append(col_name)

    return columns

def load_document_data(doc_name, dir_path):
    """Load data from a document file."""
    file_path = os.path.join(dir_path, f"{doc_name}.sql")
    if not os.path.exists(file_path):
        return []

    columns = parse_table_structure(file_path)
    raw_data = parse_sql_file(file_path)

    # Convert to list of dicts
    data = []
    for row in raw_data:
        row_dict = {}
        for i, col in enumerate(columns):
            if i < len(row):
                row_dict[col] = row[i]
        data.append(row_dict)

    return data

def epoch_day_to_date(epoch_day):
    """Convert epoch day to YYYY-MM-DD string."""
    if epoch_day is None:
        return None
    base_date = datetime(1970, 1, 1)
    target_date = base_date + timedelta(days=epoch_day)
