def parse_sql_file(file_path):
    """Parse SQL file to extract table data."""
    with open(file_path, 'r') as f:
        content = f.read()

    # Find INSERT statements
    insert_matches = re.findall(r'INSERT INTO \w+ \((.*?)\) VALUES\s*(.*?);', content, re.DOTALL | re.IGNORECASE)

    if not insert_matches:
        return []

    # Parse column names from first INSERT
    columns = [col.strip() for col in insert_matches[0][0].split(',')]

    # Parse all value tuples
    all_values = []
    for _, values_str in insert_matches:
        # Split by rows, handling multi-line values
        rows = values_str.strip().split('\n')
        for row in rows:
            row = row.strip()
            if not row or row.startswith('--'):
                continue
            # Remove parentheses and split
            if row.startswith('(') and row.endswith(')'):
                row = row[1:-1]
            # Handle NULL values and quoted strings
            parts = []
            current = ''
            in_quotes = False
            for char in row:
                if char == "'" and not (len(current) > 0 and current[-1] == '\\'):
                    in_quotes = not in_quotes
                    current += char
                elif char == ',' and not in_quotes:
                    parts.append(current.strip())
                    current = ''
                else:
                    current += char
            if current:
                parts.append(current.strip())

            # Convert values
            row_values = []
            for val in parts:
                if val.upper() == 'NULL':
                    row_values.append(None)
                elif val.startswith("'") and val.endswith("'"):
                    row_values.append(val[1:-1])
