import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_edi_file(file_path: Path) -> List[Dict]:
    """Parse EDI file and return list of records (each record is a dict)."""
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find LX segments which mark start of records
    current_record = {}
    in_record = False
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Skip header segments
        if line.startswith(('ISA', 'GS', 'ST', 'BGN', 'NTE', 'CTT', 'SE', 'GE', 'IEA')):
            continue

        segments = line.split('~')
        for segment in segments:
            if not segment:
                continue

            fields = segment.split('*')
            seg_id = fields[0]

            if seg_id == 'LX':
                # Start new record
                if current_record:
                    records.append(current_record)
                current_record = {'LX': fields[1]}
                in_record = True
            elif in_record:
                if seg_id == 'REF':
                    qualifier = fields[1]
                    value = fields[2] if len(fields) > 2 else ''
                    if qualifier not in current_record:
                        current_record[qualifier] = []
                    current_record[qualifier].append(value)
                elif seg_id == 'N1':
                    entity_type = fields[1]
                    entity_name = fields[2] if len(fields) > 2 else ''
                    if entity_type == 'EM':
                        current_record['EM'] = entity_name
                elif seg_id == 'DTP':
                    qualifier = fields[1]
                    date_type = fields[2]
                    date_value = fields[3] if len(fields) > 3 else ''
                    if qualifier not in current_record:
                        current_record[qualifier] = []
                    current_record[qualifier].append(date_value)
                elif seg_id == 'REF' and len(fields) > 2:
                    # Handle REF segments with qualifiers
                    qualifier = fields[1]
                    value = fields[2]
                    if qualifier not in current_record:
                        current_record[qualifier] = []
                    current_record[qualifier].append(value)

    # Add last record
    if current_record:
        records.append(current_record)

    return records

def extract_fact_from_document(entity_id: str, document_name: str, 
                               fact_type: str, records: Dict[str, List[Dict]]) -> Tuple[Optional[str], Optional[str]]:
    """Extract a fact value for an entity from a specific document.

    Returns: (value, document_name) or (None, None) if not found.
    """
    if document_name not in records:
        return None, None

    doc_records = records[document_name]

    # Map fact types to EDI qualifiers
    fact_mapping = {
        'authorization expiry': {
            'work_authorizations': '036',  # DTP*036 = Employability evidence lapses
            'ead_cards': '438'             # DTP*438 = Last valid day on I-766 card
        },
        'reverification date': {
            'reverifications': '572'       # DTP*572 = Supplement B executed
        },
        'notice posted': {
            'lca_notices': '196'           # DTP*196 = Notice display began
        },
        'notice removed': {
            'lca_notices': '197'           # DTP*197 = Notice display ended
        },
        'LCA filed': {
            'lca_filings': '640',          # DTP*640 = ETA-9035 submitted
            'dol_receipts': '009'          # DTP*009 = OFLC logged intake
        }
    }

    # Find all records for this entity
    entity_records = []
    for record in doc_records:
        if 'EI' in record and entity_id in record['EI']:
            entity_records.append(record)

    if not entity_records:
        return None, None

    # Get the qualifier for this fact type in this document
    if fact_type not in fact_mapping:
        return None, None

    doc_key = document_name.replace('.edi', '')
    if doc_key not in fact_mapping[fact_type]:
        return None, None

    qualifier = fact_mapping[fact_type][doc_key]

    # Collect all values for this qualifier
    values = []
    for record in entity_records:
        if qualifier in record:
            for date_str in record[qualifier]:
                if date_str:
                    values.append(date_str)

    if not values:
        return None, None

    # Check for conflicts (different values in same document)
    unique_values = list(set(values))
    if len(unique_values) > 1:
        return "CONFLICT", document_name

    # Format date from CCYYMMDD to YYYY-MM-DD
    date_str = unique_values[0]
    if len(date_str) == 8 and date_str.isdigit():
        formatted_date = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
        return formatted_date, document_name

    return date_str, document_name

def get_fact_value(entity_id: str, fact_type: str, rule_type: str, 
                   records: Dict[str, List[Dict]]) -> Union[str, List[str]]:
    """Get fact value according to decision rules."""

    if rule_type == "wf.reverify_window":
        if fact_type == "authorization expiry":
            # Try work_authorizations first
            value, doc = extract_fact_from_document(entity_id, "work_authorizations.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]

            # Fallback to ead_cards
            value, doc = extract_fact_from_document(entity_id, "ead_cards.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]

            return "ABSENT"

        elif fact_type == "reverification date":
            value, doc = extract_fact_from_document(entity_id, "reverifications.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]
            return "ABSENT"

    elif rule_type == "wf.notice_posting":
        if fact_type == "notice posted":
            value, doc = extract_fact_from_document(entity_id, "lca_notices.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]
            return "ABSENT"

        elif fact_type == "notice removed":
            value, doc = extract_fact_from_document(entity_id, "lca_notices.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]
            return "ABSENT"

        elif fact_type == "LCA filed":
            # Try lca_filings first
            value, doc = extract_fact_from_document(entity_id, "lca_filings.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
