                return [value, doc]

            # Fallback to dol_receipts
            value, doc = extract_fact_from_document(entity_id, "dol_receipts.edi", 
                                                   fact_type, records)
            if value is not None:
                if value == "CONFLICT":
                    return "CONFLICT"
                return [value, doc]

            return "ABSENT"

    return "ABSENT"

def main(directory_path: str):
    # Read all EDI files
    records = {}
    edi_files = [
        "dol_receipts.edi",
        "ead_cards.edi", 
