import sys
import os
import json
import re
from datetime import datetime, timedelta
from collections import defaultdict

def parse_edi_file(file_path):
    """
    Parse an EDI file and extract records keyed by EI (Employer-Assigned Worker File Number).
    Each record is a dictionary of field values from the segments in that LX loop.
    """
    records = defaultdict(list)  # EI -> list of records (each record is a dict)
    current_record = {}
    in_lx = False
    ei = None

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            # EDI segments are separated by *
            parts = line.split('*')
            segment_id = parts[0] if parts else ''

            if segment_id == 'LX':
                # Save previous record if any
                if in_lx and ei is not None and current_record:
                    records[ei].append(current_record.copy())
                # Start new record
                current_record = {}
                in_lx = True
                ei = None
            elif segment_id == 'REF' and in_lx:
                qualifier = parts[1] if len(parts) > 1 else ''
                value = parts[2] if len(parts) > 2 else ''
                if qualifier == 'EI':
                    ei = value
                    current_record['EI'] = value
                else:
                    # Store other REFs with qualifier as key
                    current_record[f'REF_{qualifier}'] = value
            elif segment_id == 'DTP' and in_lx:
                qualifier = parts[1] if len(parts) > 1 else ''
                # format_qualifier = parts[2] if len(parts) > 2 else ''
                date_str = parts[3] if len(parts) > 3 else ''
                if date_str:
                    # Convert CCYYMMDD to YYYY-MM-DD
                    if len(date_str) == 8 and date_str.isdigit():
                        formatted = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
                        current_record[f'DTP_{qualifier}'] = formatted
            elif segment_id == 'N1' and in_lx:
                entity_code = parts[1] if len(parts) > 1 else ''
                name = parts[2] if len(parts) > 2 else ''
                if entity_code == 'EM':
                    current_record['EMPLOYER'] = name
            elif segment_id in ('CTT', 'SE', 'GE', 'IEA'):
                # End of transaction, save last record
                if in_lx and ei is not None and current_record:
                    records[ei].append(current_record.copy())
                break  # We only need the data loops, stop after transaction end

    # Save the last record if file ends without terminal segment
    if in_lx and ei is not None and current_record:
        records[ei].append(current_record.copy())

    return records

def extract_fact_from_document(ei, document_name, parsed_docs, fact_spec):
    """
    Extract a fact for entity EI from a specific document according to fact_spec.
    fact_spec: dict with keys:
      - 'field': the field to extract (e.g., 'DTP_036' for authorization expiry)
      - 'fallback_doc': optional, name of fallback document
      - 'fallback_field': optional, field in fallback document
    Returns tuple (value, doc_used) or (None, None) if not found.
    If multiple records exist for EI in the primary document, check for conflict.
    """
    primary_doc = document_name
    fallback_doc = fact_spec.get('fallback_doc')
    field = fact_spec['field']
    fallback_field = fact_spec.get('fallback_field')

    # Check primary document
    if primary_doc in parsed_docs and ei in parsed_docs[primary_doc]:
        records = parsed_docs[primary_doc][ei]
        values = set()
        for rec in records:
            if field in rec:
                values.add(rec[field])
        if len(values) == 1:
            return (list(values)[0], primary_doc)
        elif len(values) > 1:
            return ("CONFLICT", primary_doc)
        # No value in primary
        # Try fallback if specified
        if fallback_doc and fallback_field:
            if fallback_doc in parsed_docs and ei in parsed_docs[fallback_doc]:
                records_fb = parsed_docs[fallback_doc][ei]
                values_fb = set()
                for rec in records_fb:
                    if fallback_field in rec:
                        values_fb.add(rec[fallback_field])
                if len(values_fb) == 1:
                    return (list(values_fb)[0], fallback_doc)
                elif len(values_fb) > 1:
                    return ("CONFLICT", fallback_doc)
    # Not found in primary, and no fallback or fallback not found
    return ("ABSENT", None)

def main(directory):
    # Map file names to our internal keys
    file_map = {
        'dol_receipts.edi': 'dol_receipts',
        'ead_cards.edi': 'ead_cards',
        'hr_roster.edi': 'hr_roster',
        'lca_filings.edi': 'lca_filings',
        'lca_notices.edi': 'lca_notices',
        'reverifications.edi': 'reverifications',
        'work_authorizations.edi': 'work_authorizations'
    }

    parsed_docs = {}
    for filename, doc_key in file_map.items():
        filepath = os.path.join(directory, filename)
        if os.path.exists(filepath):
            parsed_docs[doc_key] = parse_edi_file(filepath)
        else:
            parsed_docs[doc_key] = {}

    # Define fact extraction rules for each pair type
    fact_rules = {
        'wf.reverify_window': {
            'authorization expiry': {
                'field': 'DTP_036',
                'fallback_doc': 'ead_cards',
                'fallback_field': 'DTP_438'
            },
            'reverification date': {
                'field': 'DTP_572',
                'fallback_doc': None,
                'fallback_field': None
            }
        },
        'wf.notice_posting': {
            'notice posted': {
                'field': 'DTP_196',
                'fallback_doc': None,
                'fallback_field': None
            },
            'notice removed': {
                'field': 'DTP_197',
                'fallback_doc': None,
                'fallback_field': None
            },
            'LCA filed': {
                'field': 'DTP_640',
                'fallback_doc': 'dol_receipts',
                'fallback_field': 'DTP_009'
            }
        }
    }

    # Pairs to evaluate (from the problem statement)
    pairs = [
        'wf.reverify_window::E-40401',
        'wf.reverify_window::E-40402',
        'wf.reverify_window::E-40403',
        'wf.reverify_window::E-40404',
        'wf.reverify_window::E-40405',
        'wf.reverify_window::E-40406',
        'wf.reverify_window::E-40407',
        'wf.reverify_window::E-40408',
        'wf.reverify_window::E-40409',
        'wf.reverify_window::E-40410',
        'wf.reverify_window::E-40411',
        'wf.reverify_window::E-40412',
        'wf.reverify_window::E-40413',
        'wf.reverify_window::E-40414',
        'wf.reverify_window::E-40415',
        'wf.reverify_window::E-40416',
        'wf.notice_posting::E-40401',
        'wf.notice_posting::E-40402',
        'wf.notice_posting::E-40403',
        'wf.notice_posting::E-40404',
        'wf.notice_posting::E-40405',
        'wf.notice_posting::E-40406',
        'wf.notice_posting::E-40407',
        'wf.notice_posting::E-40408',
        'wf.notice_posting::E-40409',
        'wf.notice_posting::E-40410',
        'wf.notice_posting::E-40411',
        'wf.notice_posting::E-40412',
        'wf.notice_posting::E-40413',
        'wf.notice_posting::E-40414',
        'wf.notice_posting::E-40415',
        'wf.notice_posting::E-40416'
    ]

    result = {}
    for pair in pairs:
        rule_id, ei = pair.split('::')
        rule = fact_rules[rule_id]
        fact_values = {}
        for fact_name, spec in rule.items():
            value, doc_used = extract_fact_from_document(ei, spec.get('primary_doc', None), parsed_docs, spec)
            if value == "ABSENT":
                fact_values[fact_name] = "ABSENT"
            elif value == "CONFLICT":
                fact_values[fact_name] = "CONFLICT"
            else:
                # Determine which document was actually used
                # For primary/fallback logic, we need to know which document provided the value
                # The extract function already returns doc_used
                if doc_used:
                    # Map internal doc key back to filename for output
                    doc_filename = None
                    for fname, dkey in file_map.items():
                        if dkey == doc_used:
                            doc_filename = fname
                            break
                    fact_values[fact_name] = [value, doc_filename]
                else:
                    # Should not happen if value is present
                    fact_values[fact_name] = [value, "UNKNOWN"]
        result[pair] = fact_values

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
