import sys
import os
import json
import re
from datetime import datetime, timedelta
from collections import defaultdict

def parse_date(text):
    """Parse a date from various formats in the text."""
    # Remove ordinal suffixes and commas
    text = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', text)
    text = re.sub(r',', '', text)

    # Common patterns
    patterns = [
        r'(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})',
        r'(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{1,2})\w*\s+(\d{4})',
        r'(\d{4})-(\d{2})-(\d{2})',
        r'(\d{1,2})/(\d{1,2})/(\d{4})',
    ]

    month_map = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            groups = match.groups()
            if len(groups) == 3:
                if groups[1].lower() in month_map:  # Month in middle
                    day, month_str, year = groups
                    month = month_map[month_str.lower()]
                    return f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
                elif groups[0].lower() in month_map:  # Month first
                    month_str, day, year = groups
                    month = month_map[month_str.lower()]
                    return f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
                else:  # YYYY-MM-DD
                    year, month, day = groups
                    return f"{int(year):04d}-{int(month):02d}-{int(day):02d}"

    return None

def extract_entity_id(text):
    """Extract entity ID like E-40401 from text."""
    match = re.search(r'E-\d{5}', text)
    return match.group(0) if match else None

def parse_dol_receipts(content):
    """Parse dol_receipts.txt file."""
    records = defaultdict(list)

    # Split by message separator
    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        # Extract entity ID from subject
        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
            continue

        entity = entity_match.group(1)

        # Check for "No acknowledgment date" or similar
        if re.search(r'no.*acknowledgment|not.*on hand', msg, re.IGNORECASE):
            records[entity].append({
                'value': None,
                'document': 'dol_receipts'
            })
            continue

        # Look for date in message body
        date_match = re.search(r'acknowledged.*?on\s+([^.,]+)|dated\s+([^.,]+)', msg, re.IGNORECASE)
        if date_match:
            date_text = date_match.group(1) or date_match.group(2)
            date = parse_date(date_text)
            if date:
                records[entity].append({
                    'value': date,
                    'document': 'dol_receipts'
                })

    return records

def parse_ead_cards(content):
    """Parse ead_cards.txt file."""
    records = defaultdict(list)

    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
            continue

        entity = entity_match.group(1)

        # Look for end date
        date_match = re.search(r'runs to\s+([^.,]+)|end date of\s+([^.,]+)', msg, re.IGNORECASE)
        if date_match:
            date_text = date_match.group(1) or date_match.group(2)
            date = parse_date(date_text)
            if date:
                records[entity].append({
                    'value': date,
                    'document': 'ead_cards'
                })

    return records

def parse_hr_roster(content):
    """Parse hr_roster.txt file."""
    # Not needed for current rules but parsing for completeness
    return {}

def parse_lca_filings(content):
    """Parse lca_filings.txt file."""
    records = defaultdict(list)

    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
