        entity = entity_match.group(1)

        # Check for "don't have" or similar
        if re.search(r"don't have|I don't have|no.*submission", msg, re.IGNORECASE):
            records[entity].append({
                'value': None,
                'document': 'lca_filings'
            })
            continue

        # Look for submission date
        date_match = re.search(r'submitted.*?on\s+([^.,]+)|pushed.*?on\s+([^.,]+)|went in.*?on\s+([^.,]+)', msg, re.IGNORECASE)
        if date_match:
            date_text = date_match.group(1) or date_match.group(2) or date_match.group(3)
            date = parse_date(date_text)
            if date:
                records[entity].append({
                    'value': date,
                    'document': 'lca_filings'
                })

    return records

def parse_lca_notices(content):
    """Parse lca_notices.txt file."""
    records = defaultdict(lambda: {'posted': [], 'removed': []})

    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
            continue

        entity = entity_match.group(1)

        # Check for "can't tell" or similar
        if re.search(r"can't tell|I can't tell", msg, re.IGNORECASE):
            records[entity]['posted'].append({
                'value': None,
                'document': 'lca_notices'
            })
            # Still check for removal date
            pass

        # Look for posted date
        posted_match = re.search(r'went up.*?on\s+([^.,]+)|pinned.*?up on\s+([^.,]+)', msg, re.IGNORECASE)
        if posted_match:
            date_text = posted_match.group(1) or posted_match.group(2)
            date = parse_date(date_text)
            if date:
                records[entity]['posted'].append({
                    'value': date,
                    'document': 'lca_notices'
                })

        # Look for removed date
        removed_match = re.search(r'came down.*?(\d+)\s+days|later|pulled.*?down on\s+([^.,]+)|taken off.*?on\s+([^.,]+)', msg, re.IGNORECASE)
        if removed_match:
            if removed_match.group(1):  # "came down X days later"
                # Need posted date to calculate removal date
                if records[entity]['posted'] and records[entity]['posted'][-1]['value']:
                    posted_date = datetime.strptime(records[entity]['posted'][-1]['value'], '%Y-%m-%d')
                    days = int(removed_match.group(1))
                    removed_date = posted_date + timedelta(days=days)
                    records[entity]['removed'].append({
                        'value': removed_date.strftime('%Y-%m-%d'),
                        'document': 'lca_notices'
                    })
            else:  # Specific date
                date_text = removed_match.group(2) or removed_match.group(3)
                date = parse_date(date_text)
                if date:
                    records[entity]['removed'].append({
                        'value': date,
                        'document': 'lca_notices'
                    })

    return records

def parse_reverifications(content):
    """Parse reverifications.txt file."""
    records = defaultdict(list)

    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
            continue

        entity = entity_match.group(1)

        # Check for "no sign-off" or similar
        if re.search(r'no.*sign-off|not.*done', msg, re.IGNORECASE):
            records[entity].append({
                'value': None,
                'document': 'reverifications'
            })
            continue

        # Look for completion date
        date_match = re.search(r'finished.*?on\s+([^.,]+)|signed off.*?on\s+([^.,]+)', msg, re.IGNORECASE)
        if date_match:
            date_text = date_match.group(1) or date_match.group(2)
            date = parse_date(date_text)
            if date:
                records[entity].append({
                    'value': date,
                    'document': 'reverifications'
                })

    return records

def parse_work_authorizations(content):
    """Parse work_authorizations.txt file."""
    records = defaultdict(list)

    messages = re.split(r'={80,}', content)

    for msg in messages:
        if not msg.strip():
            continue

        entity_match = re.search(r'Subject:.*(E-\d{5})', msg, re.IGNORECASE)
        if not entity_match:
            continue

        entity = entity_match.group(1)

        # Check for "no end-of-validity" or similar
        if re.search(r'no.*end.*validity|not.*valid', msg, re.IGNORECASE):
            records[entity].append({
                'value': None,
                'document': 'work_authorizations'
            })
            continue

        # Look for expiry date
        date_match = re.search(r'good.*?up to\s+([^.,]+)|stops.*?valid on\s+([^.,]+)|expires.*?on\s+([^.,]+)', msg, re.IGNORECASE)
        if date_match:
            date_text = date_match.group(1) or date_match.group(2) or date_match.group(3)
            date = parse_date(date_text)
            if date:
                records[entity].append({
                    'value': date,
                    'document': 'work_authorizations'
                })

    return records

def get_fact_value(entity, fact_name, parsed_data):
    """Get value for a fact according to decision rules."""

    if fact_name == 'authorization expiry':
        # First try work_authorizations
        work_auth = parsed_data['work_authorizations'].get(entity, [])
        if work_auth:
            values = [r['value'] for r in work_auth if r['value'] is not None]
            if not values:
                return "ABSENT"
            # Check for conflicts
            unique_values = set(values)
            if len(unique_values) > 1:
                return "CONFLICT"
            return [list(unique_values)[0], 'work_authorizations']

        # Fallback to ead_cards
        ead_cards = parsed_data['ead_cards'].get(entity, [])
        if ead_cards:
            values = [r['value'] for r in ead_cards if r['value'] is not None]
            if not values:
                return "ABSENT"
            unique_values = set(values)
            if len(unique_values) > 1:
                return "CONFLICT"
