def parse_date(text):
    """Parse a date from various text formats found in the files."""
    if not text:
        return None
    # Remove ordinal suffixes and extra words
    text = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', text)
    # Common patterns
    patterns = [
        r'(\d{1,2})\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})',
        r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})',
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})',
        r'(\d{4})-(\d{2})-(\d{2})',
    ]
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            groups = match.groups()
            if len(groups) == 2:
                # Month name and year, day is first group
                day = int(groups[0])
                year = int(groups[1])
                # Extract month from text
                month_match = re.search(r'(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)', text, re.IGNORECASE)
                if month_match:
                    month_str = month_match.group(1).lower()
                    month_map = {
                        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
                        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
                    }
                    month = month_map[month_str]
                    return datetime(year, month, day).date()
            elif len(groups) == 3:
                # Could be day-month-year or month-day-year depending on pattern
                # Try to determine format
                if pattern == r'(\d{4})-(\d{2})-(\d{2})':
                    year, month, day = map(int, groups)
                    return datetime(year, month, day).date()
                else:
                    # Assume month-day-year if month > 12, otherwise day-month-year
                    a, b, c = map(int, groups)
                    if a > 12:  # day-month-year
                        day, month, year = a, b, c
                    else:  # month-day-year
                        month, day, year = a, b, c
                    return datetime(year, month, day).date()
    return None

