import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_iso_week_date(week_str):
    """Parse ISO week date YYYY-Www-D to datetime.date."""
    if week_str == "~":
        return None
    try:
        year, week, day = map(int, week_str.replace("W", "-").replace("-", "-").split("-"))
        # ISO week date: year is ISO year, week 1-53, day 1=Monday..7=Sunday
        # Use strptime with %G, %V, %u (requires Python 3.6+)
        return datetime.strptime(f"{year}-W{week:02d}-{day}", "%G-W%V-%u").date()
    except Exception:
        return None

def read_tsv_file(filepath):
    """Read a TSV file with cross-tab orientation.
    Returns dict: {worker_key: {attribute: value}}.
    """
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\n') for line in f if not line.startswith('#') and line.strip()]
    if not lines:
        return data
    headers = lines[0].split('\t')
    # First column is 'attribute', rest are rec.01, rec.02, ...
    rec_columns = headers[1:]
    # Build mapping from column index to worker key
    worker_keys = {}
    for row in lines[1:]:
        parts = row.split('\t')
        if len(parts) < len(headers):
            continue
        attr = parts[0]
        if attr == 'worker.key':
            for i, key in enumerate(parts[1:], start=1):
                if i-1 < len(rec_columns):
                    worker_keys[rec_columns[i-1]] = key
            break
    # Now collect data per worker
    for row in lines[1:]:
        parts = row.split('\t')
        if len(parts) < len(headers):
            continue
        attr = parts[0]
        for i, val in enumerate(parts[1:], start=1):
