    fact_to_attr = {
        'authorization expiry': 'eligibility.doc.lapse.wk',
        'reverification date': 'i9.redo.done.wk',
        'notice posted': 'board.pinned.wk',
        'notice removed': 'board.unpinned.wk',
        'LCA filed': 'lca.lodge.wk',
    }
    attr = fact_to_attr[fact_name]

    # For authorization expiry, also need card expiry from ead_cards as fallback
    if fact_name == 'authorization expiry':
        primary_doc = 'work_authorizations'
        fallback_doc = 'ead_cards'
        fallback_attr = 'ead.lapse.wk'
    elif fact_name == 'LCA filed':
        primary_doc = 'lca_filings'
        fallback_doc = 'dol_receipts'
        fallback_attr = 'agency.stamp.wk'
    else:
        primary_doc = docs[0]  # first listed document
        fallback_doc = None
        fallback_attr = None

    # Check primary document
    primary_data = docs.get(primary_doc, {})
    worker_data = primary_data.get(worker, {})
    if attr in worker_data:
        value = worker_data[attr]
        # Check for conflicts: multiple records for same worker in same doc?
        # In cross-tab, each column is separate record, but worker.key may repeat.
        # We need to detect if same worker appears in multiple columns with different values.
        all_values = []
        for w, attrs in primary_data.items():
            if w == worker and attr in attrs:
                all_values.append(attrs[attr])
        if len(set(all_values)) > 1:
            return "CONFLICT"
        return [value, primary_doc]

    # If primary has no value, use fallback if defined
    if fallback_doc and fallback_attr:
        fallback_data = docs.get(fallback_doc, {})
        worker_fallback = fallback_data.get(worker, {})
        if fallback_attr in worker_fallback:
            value = worker_fallback[fallback_attr]
            # Check for conflicts in fallback document
            all_values = []
            for w, attrs in fallback_data.items():
                if w == worker and fallback_attr in attrs:
                    all_values.append(attrs[fallback_attr])
            if len(set(all_values)) > 1:
                return "CONFLICT"
            return [value, fallback_doc]

    return "ABSENT"

