        return None
    try:
        return datetime.strptime(date_str.strip(), "%m/%d/%Y").date()
    except ValueError:
        return None

def read_document(file_path, entity_field, value_fields):
    """
    Read a document file and return a dict mapping entity_id (WORKER_FILE_NUMBER) 
    to a dict of field values.
    """
    data = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find header line (first non-comment line)
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split('|')
            break

    if not header:
        return data

    # Map column names to indices
    col_index = {col: i for i, col in enumerate(header)}

    # Process data lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip() == '|'.join(header):
            continue  # Skip header if repeated

        parts = line.strip().split('|')
        if len(parts) != len(header):
            continue

        entity_id = parts[col_index[entity_field]].strip()
        if not entity_id:
            continue

        # Extract values for requested fields
        values = {}
        for field in value_fields:
            if field in col_index:
                raw_value = parts[col_index[field]].strip()
                # Parse dates if field name suggests it
                if any(date_keyword in field.lower() for date_keyword in ['date', 'day', 'begin', 'end', 'to', 'executed', 'lapse', 'valid']):
                    values[field] = parse_date(raw_value)
                else:
                    values[field] = raw_value if raw_value != '' else None
            else:
                values[field] = None

        # If entity already exists, check for conflicts
        if entity_id in data:
            existing = data[entity_id]
            conflict = False
            for field in value_fields:
                if field in existing and field in values:
                    if existing[field] != values[field]:
                        conflict = True
                        break
            if conflict:
                # Mark as conflict
                data[entity_id] = {'CONFLICT': True}
            # If no conflict, keep first occurrence (as per "first listed document")
        else:
            data[entity_id] = values

    return data

def main(directory):
    dir_path = Path(directory)

    # Read all documents
    documents = {}

    # wf.reverify_window facts
    # authorization expiry: work_authorizations.EMPLOYABILITY_EVIDENCE_LAPSE, fallback ead_cards.I766_VALID_TO
    # reverification date: reverifications.SUPPLEMENT_B_EXECUTED

    # wf.notice_posting facts
    # notice posted: lca_notices.NOTICE_DISPLAY_BEGIN
    # notice removed: lca_notices.NOTICE_DISPLAY_END
    # LCA filed: lca_filings.ETA9035_SUBMISSION_DAY, fallback dol_receipts.OFLC_INTAKE_DAY

    # Read work_authorizations for authorization expiry
    work_auth_path = dir_path / "work_authorizations.txt"
    work_auth_data = read_document(
        work_auth_path, 
        "WORKER_FILE_NUMBER",
        ["EMPLOYABILITY_EVIDENCE_LAPSE"]
    )

    # Read ead_cards for fallback authorization expiry
    ead_cards_path = dir_path / "ead_cards.txt"
    ead_cards_data = read_document(
        ead_cards_path,
        "WORKER_FILE_NUMBER",
        ["I766_VALID_TO"]
    )

    # Read reverifications for reverification date
    reverifications_path = dir_path / "reverifications.txt"
    reverifications_data = read_document(
        reverifications_path,
        "WORKER_FILE_NUMBER",
