    )

    # Read dol_receipts for fallback LCA filed date
    dol_receipts_path = dir_path / "dol_receipts.txt"
    dol_receipts_data = read_document(
        dol_receipts_path,
        "WORKER_FILE_NUMBER",
        ["OFLC_INTAKE_DAY"]
    )

    # Prepare result structure
    result = {}

    # Process all pairs (E-40601 through E-40616 for both rules)
    for entity_id in [f"E-406{i:02d}" for i in range(1, 17)]:
        # wf.reverify_window
        rule_id = f"wf.reverify_window::{entity_id}"
        result[rule_id] = {}

        # Fact: authorization expiry
        auth_expiry = None
        auth_doc = None

        # Check work_authorizations first
        if entity_id in work_auth_data:
            if 'CONFLICT' in work_auth_data[entity_id]:
                result[rule_id]["authorization expiry"] = "CONFLICT"
            else:
                auth_expiry = work_auth_data[entity_id].get("EMPLOYABILITY_EVIDENCE_LAPSE")
