                    result[rule_id]["notice removed"] = "ABSENT"
        else:
            result[rule_id]["notice posted"] = "ABSENT"
            result[rule_id]["notice removed"] = "ABSENT"

        # Fact: LCA filed
        lca_filed = None
        lca_doc = None

        # Check lca_filings first
        if entity_id in lca_filings_data:
            if 'CONFLICT' in lca_filings_data[entity_id]:
