            else:
                result[rule_id]["LCA filed"] = "ABSENT"

    # Output JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
