from datetime import datetime, timedelta
from collections import defaultdict

def parse_date(date_str):
    """Parse MM/DD/YYYY date string to datetime.date, return None if empty or invalid."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%m/%d/%Y").date()
    except ValueError:
        return None

def read_document(file_path):
    """Read a document file, skip comments, parse header and rows."""
    data = []
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    # Find first non-comment line as header
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split('|')
            break
    if not header:
        return []
    # Process remaining non-comment lines
    for line in lines:
        if line.startswith('#'):
            continue
        if line.strip() == header:
            continue
        parts = line.strip().split('|')
        if len(parts) != len(header):
            continue
        row = dict(zip(header, parts))
        data.append(row)
    return data

def load_documents(dir_path):
    """Load all document files from directory."""
    files = {
        'dol_receipts': 'dol_receipts.txt',
        'ead_cards': 'ead_cards.txt',
        'hr_roster': 'hr_roster.txt',
        'lca_filings': 'lca_filings.txt',
        'lca_notices': 'lca_notices.txt',
        'reverifications': 'reverifications.txt',
        'work_authorizations': 'work_authorizations.txt'
    }
    docs = {}
    for key, filename in files.items():
        file_path = os.path.join(dir_path, filename)
        if os.path.exists(file_path):
            docs[key] = read_document(file_path)
        else:
            docs[key] = []
    return docs

def get_entity_rows(docs, doc_name, entity_id):
    """Get all rows for a given entity (WORKER_FILE_NUMBER) from a document."""
    rows = []
    for row in docs.get(doc_name, []):
        if row.get('WORKER_FILE_NUMBER') == entity_id:
            rows.append(row)
    return rows

def extract_fact_value(docs, rule):
    """
    Extract fact value according to rule.
    rule: tuple (fact_name, primary_doc, field, fallback_doc=None, fallback_field=None)
    Returns (value, source_doc) or "ABSENT" or "CONFLICT".
    """
    fact_name, primary_doc, field, fallback_doc, fallback_field = rule
    entity_id = rule[-1]  # last element is entity_id

    # Get rows from primary document
    primary_rows = get_entity_rows(docs, primary_doc, entity_id)

    # Determine if we need to check fallback
    use_fallback = False
    if not primary_rows:
        use_fallback = True
    else:
        # Check if any primary row has a value for the field
        has_value = False
        for row in primary_rows:
            if row.get(field, '').strip() != '':
                has_value = True
                break
        if not has_value:
            use_fallback = True

    if use_fallback and fallback_doc:
        # Use fallback document
        fallback_rows = get_entity_rows(docs, fallback_doc, entity_id)
        if not fallback_rows:
            return "ABSENT"

        # Collect values from fallback rows
        values = set()
        for row in fallback_rows:
            val = row.get(fallback_field, '').strip()
            if val:
                values.add(val)

        if len(values) == 0:
            return "ABSENT"
        elif len(values) == 1:
            return [list(values)[0], fallback_doc]
        else:
            return "CONFLICT"
    else:
        # Use primary document
        if not primary_rows:
            return "ABSENT"

        # Collect values from primary rows
        values = set()
        for row in primary_rows:
            val = row.get(field, '').strip()
            if val:
                values.add(val)

        if len(values) == 0:
            return "ABSENT"
        elif len(values) == 1:
            return [list(values)[0], primary_doc]
        else:
            return "CONFLICT"

def main():
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    dir_path = sys.argv[1]
    docs = load_documents(dir_path)

    # Define rules for each pair type
    results = {}

    # Process all entities E-40701 through E-40716
    entities = [f"E-407{i:02d}" for i in range(1, 17)]

    for entity in entities:
        # wf.reverify_window rules
        auth_expiry_rule = ('authorization expiry', 'work_authorizations', 
                           'EMPLOYABILITY_EVIDENCE_LAPSE', 'ead_cards', 'I766_VALID_TO', entity)
        reverify_date_rule = ('reverification date', 'reverifications', 
                             'SUPPLEMENT_B_EXECUTED', None, None, entity)

        auth_result = extract_fact_value(docs, auth_expiry_rule)
        reverify_result = extract_fact_value(docs, reverify_date_rule)

        results[f"wf.reverify_window::{entity}"] = {
            'authorization expiry': auth_result,
            'reverification date': reverify_result
        }

        # wf.notice_posting rules
        notice_posted_rule = ('notice posted', 'lca_notices', 'NOTICE_DISPLAY_BEGIN', 
                             None, None, entity)
        notice_removed_rule = ('notice removed', 'lca_notices', 'NOTICE_DISPLAY_END', 
                              None, None, entity)
        lca_filed_rule = ('LCA filed', 'lca_filings', 'ETA9035_SUBMISSION_DAY', 
                         'dol_receipts', 'OFLC_INTAKE_DAY', entity)

        posted_result = extract_fact_value(docs, notice_posted_rule)
        removed_result = extract_fact_value(docs, notice_removed_rule)
        lca_result = extract_fact_value(docs, lca_filed_rule)

        results[f"wf.notice_posting::{entity}"] = {
            'notice posted': posted_result,
            'notice removed': removed_result,
            'LCA filed': lca_result
        }

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
