from html.parser import HTMLParser
from collections import defaultdict

class SheetParser(HTMLParser):
    """Parse a single sheet (article) from the HTML files."""
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_key = None
        self.data = {}
        self.temp_th = ""
        self.temp_td = ""
        self.in_void = False

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            for attr, val in attrs:
                if attr == "class" and "fields" in val:
                    self.in_table = True
        elif self.in_table and tag == "th":
            self.in_th = True
            self.temp_th = ""
        elif self.in_table and tag == "td":
            self.in_td = True
            self.temp_td = ""
            for attr, val in attrs:
                if attr == "class" and "void" in val:
                    self.in_void = True
        elif tag == "strong" and self.in_td and not self.in_void:
            # badge is inside <strong> tags
            pass

    def handle_endtag(self, tag):
        if tag == "table":
            self.in_table = False
        elif tag == "th":
            self.in_th = False
            self.current_key = self.temp_th.strip()
        elif tag == "td":
            self.in_td = False
            if self.current_key and not self.in_void:
                value = self.temp_td.strip()
                if value:
                    self.data[self.current_key] = value
            self.in_void = False

    def handle_data(self, data):
        if self.in_th:
            self.temp_th += data
        elif self.in_td and not self.in_void:
            self.temp_td += data

def parse_date(date_str):
    """Convert date strings like 'Mon., April 13, 2026' to YYYY-MM-DD."""
    # Remove day of week and any trailing period
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    # Handle abbreviated months
    month_map = {
        'Jan.': 'January', 'Feb.': 'February', 'March': 'March', 'April': 'April',
        'May': 'May', 'June': 'June', 'July': 'July', 'Aug.': 'August',
        'Sept.': 'September', 'Oct.': 'October', 'Nov.': 'November', 'Dec.': 'December'
    }
    for abbr, full in month_map.items():
        if abbr in date_str:
            date_str = date_str.replace(abbr, full)
            break
    try:
        dt = datetime.strptime(date_str.strip(), '%B %d, %Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        # Try without day suffix (e.g., "1st" -> "1")
        date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)
        try:
            dt = datetime.strptime(date_str.strip(), '%B %d, %Y')
            return dt.strftime('%Y-%m-%d')
        except:
            return None

def parse_html_file(filepath):
    """Parse an HTML file and return a dict mapping badge -> {field: value}."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by article sheets
    articles = re.findall(r'<article class="sheet"[^>]*>.*?</article>', content, re.DOTALL)
    results = {}
    for art in articles:
        parser = SheetParser()
        parser.feed(art)
        data = parser.data
        if 'Staff badge' in data:
            badge = data['Staff badge']
            # Convert dates
            for key, val in list(data.items()):
                if 'date' in key.lower() or 'valid' in key.lower() or 'expires' in key.lower() or 'signed' in key.lower() or 'displayed' in key.lower() or 'withdrawn' in key.lower() or 'submitted' in key.lower() or 'ends' in key.lower() or 'submission' in key.lower():
                    parsed = parse_date(val)
                    if parsed:
                        data[key] = parsed
            results[badge] = data
    return results

def load_all_data(dir_path):
    """Load all HTML files in the directory."""
    files = {
        'dol_receipts': 'dol_receipts.html',
        'ead_cards': 'ead_cards.html',
        'hr_roster': 'hr_roster.html',
        'lca_filings': 'lca_filings.html',
        'lca_notices': 'lca_notices.html',
        'reverifications': 'reverifications.html',
        'work_authorizations': 'work_authorizations.html'
    }
    data = {}
    for key, filename in files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            data[key] = parse_html_file(filepath)
        else:
            data[key] = {}
    return data

def get_fact_value(data, badge, fact_name, rule):
    """Get value for a fact according to the rule."""
    if rule == 'authorization expiry':
        # First try work_authorizations
        if badge in data['work_authorizations']:
            doc = data['work_authorizations'][badge]
            if 'Evidence expires' in doc:
                return [doc['Evidence expires'], 'work_authorizations']
        # Fallback to ead_cards
        if badge in data['ead_cards']:
            doc = data['ead_cards'][badge]
            if 'EAD valid to' in doc:
                return [doc['EAD valid to'], 'ead_cards']
        return "ABSENT"

    elif rule == 'reverification date':
        if badge in data['reverifications']:
            doc = data['reverifications'][badge]
            if 'Supplement B signed on' in doc:
                return [doc['Supplement B signed on'], 'reverifications']
        return "ABSENT"

    elif rule == 'notice posted':
        if badge in data['lca_notices']:
            doc = data['lca_notices'][badge]
            if 'Notice first displayed' in doc:
                return [doc['Notice first displayed'], 'lca_notices']
        return "ABSENT"

    elif rule == 'notice removed':
        if badge in data['lca_notices']:
            doc = data['lca_notices'][badge]
            if 'Notice withdrawn from display' in doc:
                return [doc['Notice withdrawn from display'], 'lca_notices']
        return "ABSENT"

    elif rule == 'LCA filed':
        # First try lca_filings
        if badge in data['lca_filings']:
            doc = data['lca_filings'][badge]
            if 'Submitted through FLAG' in doc:
                return [doc['Submitted through FLAG'], 'lca_filings']
        # Fallback to dol_receipts
        if badge in data['dol_receipts']:
            doc = data['dol_receipts'][badge]
            if 'Agency receipt notice dated' in doc:
                return [doc['Agency receipt notice dated'], 'dol_receipts']
        return "ABSENT"

    return "ABSENT"

def check_conflict(values):
    """Check if there are conflicting values for the same fact."""
    if len(values) <= 1:
        return False
    first_val = values[0][0] if isinstance(values[0], list) else values[0]
    for v in values[1:]:
        curr_val = v[0] if isinstance(v, list) else v
        if curr_val != first_val:
            return True
    return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    dir_path = sys.argv[1]
    data = load_all_data(dir_path)

    # All badges from E-40701 to E-40716
    badges = [f'E-407{i:02d}' for i in range(1, 17)]

    result = {}

    # Process wf.reverify_window pairs
    for badge in badges:
        pair_id = f'wf.reverify_window::{badge}'
        facts = {}

        # Get authorization expiry
        auth_exp = get_fact_value(data, badge, 'authorization expiry', 'authorization expiry')
        facts['authorization expiry'] = auth_exp

        # Get reverification date
        reverif_date = get_fact_value(data, badge, 'reverification date', 'reverification date')
        facts['reverification date'] = reverif_date

        result[pair_id] = facts

    # Process wf.notice_posting pairs
    for badge in badges:
        pair_id = f'wf.notice_posting::{badge}'
        facts = {}

        # Get notice posted
        notice_posted = get_fact_value(data, badge, 'notice posted', 'notice posted')
        facts['notice posted'] = notice_posted

        # Get notice removed
        notice_removed = get_fact_value(data, badge, 'notice removed', 'notice removed')
        facts['notice removed'] = notice_removed

        # Get LCA filed
        lca_filed = get_fact_value(data, badge, 'LCA filed', 'LCA filed')
        facts['LCA filed'] = lca_filed

        result[pair_id] = facts

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
