def parse_epoch_day(epd):
    """Convert epoch day to YYYY-MM-DD string."""
    if epd is None:
        return None
    base = datetime(1970, 1, 1)
    date = base + timedelta(days=epd)
    return date.strftime("%Y-%m-%d")

def parse_sql_file(file_path, table_name):
    """Parse SQL file and extract records as list of dicts."""
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find INSERT statements for the table
    pattern = rf"INSERT INTO {table_name} \(([^)]+)\) VALUES \(([^)]+)\);"
    matches = re.findall(pattern, content, re.IGNORECASE | re.DOTALL)

    for match in matches:
        columns = [col.strip() for col in match[0].split(',')]
        values = [v.strip() for v in match[1].split(',')]

        # Handle NULL values
        parsed_values = []
        for v in values:
            if v.upper() == 'NULL':
                parsed_values.append(None)
            elif v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
                parsed_values.append(int(v))
            else:
                # Remove quotes from strings
