def parse_sql_file(file_path, table_name):
    """Parse a SQL file and extract rows for a given table."""
    rows = []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find the INSERT statement for the table
    pattern = rf'INSERT INTO {table_name}.*?VALUES\s*\((.*?)\);'
    # Use a more robust extraction: get all INSERT lines
    lines = content.split('\n')
    in_insert = False
    current_values = []
    for line in lines:
        line = line.strip()
        if line.startswith('INSERT INTO') and table_name in line:
            in_insert = True
            # Extract values part after VALUES
            if 'VALUES' in line:
                values_part = line.split('VALUES', 1)[1].strip()
                if values_part.startswith('('):
                    current_values.append(values_part)
        elif in_insert and line:
            if line.startswith('('):
                current_values.append(line)
            elif line.endswith(';'):
                if line.startswith('('):
                    current_values.append(line.rstrip(';'))
                in_insert = False
            elif line.startswith('INSERT'):
                in_insert = False

    # Parse all value tuples
    for val_str in current_values:
        # Clean the string
        val_str = val_str.strip()
        if val_str.startswith('('):
            val_str = val_str[1:]
        if val_str.endswith(')'):
            val_str = val_str[:-1]
        if val_str.endswith(');'):
            val_str = val_str[:-2]

        # Split by comma but handle NULL and strings with commas
        parts = []
        current = ''
        in_string = False
        for ch in val_str:
            if ch == "'" and not (len(current) > 0 and current[-1] == '\\'):
                in_string = not in_string
                current += ch
            elif ch == ',' and not in_string:
                parts.append(current.strip())
                current = ''
            else:
                current += ch
        if current:
            parts.append(current.strip())

        # Convert values
        row = []
        for p in parts:
            if p.upper() == 'NULL':
                row.append(None)
            elif p.startswith("'") and p.endswith("'"):
                row.append(p[1:-1])
            elif p.isdigit() or (p.startswith('-') and p[1:].isdigit()):
                row.append(int(p))
            else:
                # Try float for decimal strings
                try:
                    row.append(float(p))
                except:
                    row.append(p)
        rows.append(row)

    # Get column names from CREATE TABLE
    col_pattern = rf'CREATE TABLE {table_name}\s*\((.*?)\);'
    match = re.search(col_pattern, content, re.DOTALL)
    if not match:
        # Try without exact whitespace
        lines = content.split('\n')
        in_create = False
        col_lines = []
        for line in lines:
            if 'CREATE TABLE' in line and table_name in line:
                in_create = True
            if in_create:
                col_lines.append(line)
                if line.strip().endswith(')'):
                    break
        col_text = '\n'.join(col_lines)
        match = re.search(r'\((.*?)\);', col_text, re.DOTALL)

    if match:
        col_text = match.group(1)
        col_names = []
        for line in col_text.split('\n'):
            line = line.strip().strip(',')
            if line and not line.startswith('--'):
                # Get first word as column name
                parts = line.split()
                if parts:
                    col_names.append(parts[0])
    else:
        # Fallback: assume first row has right number of columns
        if rows:
            col_names = [f'col{i}' for i in range(len(rows[0]))]
        else:
            col_names = []

    # Convert to list of dicts
    result = []
    for row in rows:
        if len(row) != len(col_names):
            # Skip malformed rows
            continue
        result.append(dict(zip(col_names, row)))
    return result

