import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_edi_file(file_path):
    """
    Parse an EDI file and extract records keyed by EI (employer-assigned worker file number).
    Each record is a dictionary of field values from the segments in that LX loop.
    """
    records = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    current_lx = None
    current_record = {}
    in_loop = False

    for line in lines:
        line = line.strip()
        if not line:
            continue
        segments = line.split('~')
        for seg in segments:
            if not seg:
                continue
            parts = seg.split('*')
            seg_id = parts[0]

            if seg_id == 'LX':
                # Save previous record
                if current_lx is not None and current_record:
                    ei = current_record.get('EI')
                    if ei:
                        # If multiple loops for same EI, we need to handle conflicts
                        if ei in records:
                            # Mark as having multiple records for same EI
                            if not isinstance(records[ei], list):
                                records[ei] = [records[ei]]
                            records[ei].append(current_record)
                        else:
                            records[ei] = current_record
                    else:
                        # No EI in this loop? skip
                        pass

                # Start new loop
                current_lx = parts[1] if len(parts) > 1 else None
                current_record = {'LX': current_lx}
                in_loop = True
            elif in_loop:
                if seg_id == 'REF':
                    qual = parts[1] if len(parts) > 1 else ''
                    value = parts[2] if len(parts) > 2 else ''
                    if qual:
                        current_record[qual] = value
                elif seg_id == 'DTP':
                    qual = parts[1] if len(parts) > 1 else ''
                    # format = parts[2] if len(parts) > 2 else ''
                    value = parts[3] if len(parts) > 3 else ''
                    if qual:
                        current_record[qual] = value
                elif seg_id == 'N1':
                    qual = parts[1] if len(parts) > 1 else ''
                    value = parts[2] if len(parts) > 2 else ''
                    if qual == 'EM':
                        current_record['EM'] = value
                elif seg_id in ('BGN', 'SE', 'GE', 'IEA', 'GS', 'ISA', 'ST', 'CTT'):
                    # Control segments, ignore
                    pass
                elif seg_id == 'NTE':
                    # Notes, ignore for data extraction
                    pass
                else:
                    # Other segments, store raw?
                    pass

    # Save last record
    if current_lx is not None and current_record:
        ei = current_record.get('EI')
        if ei:
            if ei in records:
                if not isinstance(records[ei], list):
                    records[ei] = [records[ei]]
                records[ei].append(current_record)
            else:
                records[ei] = current_record

    return records

def get_value_for_entity(records, entity_id, field_name, document_name):
    """
    Get value for a specific entity and field from parsed records.
    Returns (value, document) or (None, None) if not found.
    If there are multiple records for same entity and they disagree, returns (None, None) and we'll handle conflict later.
    """
    if entity_id not in records:
        return None, None

    rec = records[entity_id]
    if isinstance(rec, list):
        # Multiple records: check for conflicts
        values = set()
        for r in rec:
            if field_name in r:
                values.add(r[field_name])
        if len(values) == 0:
            return None, None
        elif len(values) == 1:
            return values.pop(), document_name
        else:
            # Conflict
            return None, None
    else:
        if field_name in rec:
            return rec[field_name], document_name
        else:
            return None, None

def parse_date(date_str):
    """Parse date from YYYYMMDD format to YYYY-MM-DD."""
    if not date_str or len(date_str) != 8:
        return None
    try:
        return f"{date_str[0:4]}-{date_str[4:6]}-{date_str[6:8]}"
    except:
        return None

