import sys
import os
import json
import re
from datetime import datetime, timedelta
from pathlib import Path

def parse_edi_file(file_path):
    """
    Parse an EDI file and extract LX loops with their segments.
    Returns a dict mapping entity ID (REF*EI) to a list of loops for that entity.
    Each loop is a dict of segment types to their values.
    """
    data = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split into lines and process
    lines = content.split('~')
    current_loop = None
    current_entity = None
    loop_data = {}

    for line in lines:
        if not line.strip():
            continue
        segments = line.split('*')
        seg_id = segments[0] if segments else ''

        # Start of new LX loop
        if seg_id == 'LX':
            # Save previous loop if exists
            if current_entity is not None and loop_data:
                data.setdefault(current_entity, []).append(loop_data.copy())

            # Reset for new loop
            current_loop = segments[1] if len(segments) > 1 else ''
            loop_data = {'LX': current_loop}
            current_entity = None

        # Entity reference
        elif seg_id == 'REF' and len(segments) > 2 and segments[1] == 'EI':
            entity_id = segments[2]
            current_entity = entity_id
            loop_data['REF_EI'] = entity_id

        # Employer name
        elif seg_id == 'N1' and len(segments) > 2 and segments[1] == 'EM':
            loop_data['N1_EM'] = segments[2]

        # Date segments - store all DTP segments with qualifier
        elif seg_id == 'DTP' and len(segments) >= 4:
            qualifier = segments[1] if len(segments) > 1 else ''
            format_code = segments[2] if len(segments) > 2 else ''
            date_str = segments[3] if len(segments) > 3 else ''
            if format_code == 'D8' and len(date_str) == 8:
                # Convert CCYYMMDD to YYYY-MM-DD
                formatted_date = f"{date_str[0:4]}-{date_str[4:6]}-{date_str[6:8]}"
                loop_data[f'DTP_{qualifier}'] = formatted_date

        # Other REF segments
        elif seg_id == 'REF' and len(segments) > 2:
            ref_qual = segments[1]
            ref_val = segments[2]
            loop_data[f'REF_{ref_qual}'] = ref_val

    # Don't forget the last loop
    if current_entity is not None and loop_data:
        data.setdefault(current_entity, []).append(loop_data.copy())

    return data

def extract_fact_from_document(entity_id, doc_data, fact_config):
    """
    Extract a fact value for a given entity from document data.
    fact_config: dict with keys:
        - 'doc_name': name of document file (without extension)
        - 'segment': segment type to look for (e.g., 'DTP_036', 'REF_ADT')
        - 'fallback_doc': optional fallback document name
        - 'fallback_segment': optional fallback segment
    Returns: (value, document_name) or (None, None) if not found
    """
    doc_name = fact_config['doc_name']
    segment = fact_config['segment']

    if entity_id not in doc_data.get(doc_name, {}):
        # Try fallback if specified
        if 'fallback_doc' in fact_config and fact_config['fallback_doc']:
            fallback_doc = fact_config['fallback_doc']
            fallback_segment = fact_config.get('fallback_segment', segment)
            if entity_id in doc_data.get(fallback_doc, {}):
                loops = doc_data[fallback_doc][entity_id]
                values = []
                for loop in loops:
                    if fallback_segment in loop:
                        values.append(loop[fallback_segment])
                if values:
                    # Check for conflicts
                    unique_values = set(values)
                    if len(unique_values) > 1:
                        return "CONFLICT", fallback_doc
                    return values[0], fallback_doc
        return "ABSENT", None

    loops = doc_data[doc_name][entity_id]
    values = []
    for loop in loops:
        if segment in loop:
            values.append(loop[segment])

    if not values:
        return "ABSENT", None

    # Check for conflicts within the same document
    unique_values = set(values)
    if len(unique_values) > 1:
        return "CONFLICT", doc_name

    return values[0], doc_name

def main(directory_path):
    # Define document files
    doc_files = {
        'dol_receipts': 'dol_receipts.edi',
        'ead_cards': 'ead_cards.edi',
        'hr_roster': 'hr_roster.edi',
        'lca_filings': 'lca_filings.edi',
        'lca_notices': 'lca_notices.edi',
        'reverifications': 'reverifications.edi',
        'work_authorizations': 'work_authorizations.edi'
    }

    # Parse all documents
    doc_data = {}
    for doc_name, filename in doc_files.items():
        file_path = os.path.join(directory_path, filename)
        if os.path.exists(file_path):
            doc_data[doc_name] = parse_edi_file(file_path)
        else:
            doc_data[doc_name] = {}

    # Define fact configurations for each rule
    fact_configs = {
        'wf.reverify_window': {
            'authorization expiry': {
                'doc_name': 'work_authorizations',
                'segment': 'DTP_036',
                'fallback_doc': 'ead_cards',
                'fallback_segment': 'DTP_438'
            },
            'reverification date': {
                'doc_name': 'reverifications',
                'segment': 'DTP_572'
            }
        },
        'wf.notice_posting': {
            'notice posted': {
                'doc_name': 'lca_notices',
                'segment': 'DTP_196'
            },
            'notice removed': {
                'doc_name': 'lca_notices',
                'segment': 'DTP_197'
            },
            'LCA filed': {
                'doc_name': 'lca_filings',
                'segment': 'DTP_640',
                'fallback_doc': 'dol_receipts',
                'fallback_segment': 'DTP_009'
            }
        }
    }

    # Define all entity IDs (E-41001 through E-41016)
    entity_ids = [f'E-{41001 + i:05d}' for i in range(16)]

    # Process all pairs
    result = {}

    for rule_id in ['wf.reverify_window', 'wf.notice_posting']:
        for entity_id in entity_ids:
            pair_id = f"{rule_id}::{entity_id}"
            rule_facts = {}

            for fact_name, config in fact_configs[rule_id].items():
                value, source_doc = extract_fact_from_document(entity_id, doc_data, config)

                if value == "ABSENT":
                    rule_facts[fact_name] = "ABSENT"
                elif value == "CONFLICT":
                    rule_facts[fact_name] = "CONFLICT"
                else:
                    rule_facts[fact_name] = [value, source_doc]

            result[pair_id] = rule_facts

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    main(sys.argv[1])
