import json
import os
import re
import sys
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Tuple, Union

# ----------------------------------------------------------------------
# Date parsing utilities
# ----------------------------------------------------------------------

def parse_date(text: str) -> Optional[str]:
    """Parse a date string from the email body into YYYY-MM-DD format.
    Handles various formats like '17th Mar 2026', 'March 22nd, 2026', '28th Jan 2026', etc."""
    if not text:
        return None
    # Remove ordinal suffixes
    text = re.sub(r'(\d)(st|nd|rd|th)', r'\1', text)
    # Try multiple formats
    formats = [
        "%d %b %Y",   # 17 Mar 2026
        "%B %d, %Y",  # March 22, 2026
        "%d %B %Y",   # 22 March 2026
        "%b %d, %Y",  # Mar 22, 2026
        "%Y-%m-%d",   # Already formatted
    ]
    for fmt in formats:
        try:
            dt = datetime.strptime(text.strip(), fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            continue
    return None

def extract_date_from_message(body: str, patterns: List[str]) -> Optional[str]:
    """Extract a date from the email body using regex patterns."""
    for pattern in patterns:
        match = re.search(pattern, body, re.IGNORECASE)
        if match:
            date_str = match.group(1)
            parsed = parse_date(date_str)
            if parsed:
                return parsed
    return None

# ----------------------------------------------------------------------
# Document parsers
# ----------------------------------------------------------------------

def parse_dol_receipts(content: str) -> Dict[str, List[str]]:
    """Parse dol_receipts.txt and return dict mapping entity to list of dates."""
    data = {}
    # Split into messages
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        # Extract entity (E-XXXXX)
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        # Look for acknowledgment date
        patterns = [
            r'acknowledged it on ([\w\s,\.]+)',
            r'acknowledgment is dated ([\w\s,\.]+)',
            r'acknowledgment - E-\d{5}.*?(\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{4})',
            r'dated ([\w\s,\.]+)',
        ]
        date = extract_date_from_message(msg, patterns)
        if date:
            data.setdefault(entity, []).append(date)
    return data

def parse_ead_cards(content: str) -> Dict[str, List[str]]:
    """Parse ead_cards.txt and return dict mapping entity to list of end dates."""
    data = {}
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        patterns = [
            r'end date of ([\w\s,\.]+)',
            r'runs to ([\w\s,\.]+)',
            r'to ([\w\s,\.]+)',
        ]
        date = extract_date_from_message(msg, patterns)
        if date:
            data.setdefault(entity, []).append(date)
    return data

def parse_work_authorizations(content: str) -> Dict[str, List[str]]:
    """Parse work_authorizations.txt and return dict mapping entity to list of expiry dates."""
    data = {}
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        # Skip if no end date (e.g., "We have no end-of-validity")
        if re.search(r'no end-of-validity', msg, re.IGNORECASE):
            continue
        patterns = [
            r'stops being valid on ([\w\s,\.]+)',
            r'good only up to ([\w\s,\.]+)',
            r'valid on ([\w\s,\.]+)',
            r'up to ([\w\s,\.]+)',
        ]
        date = extract_date_from_message(msg, patterns)
        if date:
            data.setdefault(entity, []).append(date)
    return data

def parse_reverifications(content: str) -> Dict[str, List[str]]:
    """Parse reverifications.txt and return dict mapping entity to list of completion dates."""
    data = {}
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        patterns = [
            r'signed off on ([\w\s,\.]+)',
            r'finished the re-verification on ([\w\s,\.]+)',
            r'done on ([\w\s,\.]+)',
        ]
        date = extract_date_from_message(msg, patterns)
        if date:
            data.setdefault(entity, []).append(date)
    return data

def parse_lca_filings(content: str) -> Dict[str, List[str]]:
    """Parse lca_filings.txt and return dict mapping entity to list of filing dates."""
    data = {}
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        # Skip if no date (e.g., "I don't have a FLAG submission day")
        if re.search(r"don't have|no.*FLAG", msg, re.IGNORECASE):
            continue
        patterns = [
            r'submitted through FLAG on ([\w\s,\.]+)',
            r'pushed the LCA into FLAG on ([\w\s,\.]+)',
            r'went in on ([\w\s,\.]+)',
            r'on ([\w\s,\.]+)',
        ]
        date = extract_date_from_message(msg, patterns)
        if date:
            data.setdefault(entity, []).append(date)
    return data

def parse_lca_notices(content: str) -> Dict[str, Dict[str, List[str]]]:
    """Parse lca_notices.txt and return dict mapping entity to dict with 'posted' and 'removed' lists."""
    data = {}
    messages = re.split(r'={80,}', content)
    for msg in messages:
        if not msg.strip():
            continue
        entity_match = re.search(r'E-\d{5}', msg)
        if not entity_match:
            continue
        entity = entity_match.group(0)
        if entity not in data:
            data[entity] = {'posted': [], 'removed': []}

        # Posted date
        posted_patterns = [
            r'went up on the board on ([\w\s,\.]+)',
            r'pinned the notice up on ([\w\s,\.]+)',
            r'notice went up on ([\w\s,\.]+)',
        ]
        posted_date = extract_date_from_message(msg, posted_patterns)
        if posted_date:
            data[entity]['posted'].append(posted_date)

        # Removed date
        removed_patterns = [
            r'taken off the board on ([\w\s,\.]+)',
            r'pulled the notice down on ([\w\s,\.]+)',
            r'came down ([\w\s,\.]+) later',  # For relative dates
            r'came down on ([\w\s,\.]+)',
        ]
        # Handle relative dates (e.g., "came down 28 days later")
        if 'came down' in msg and 'days later' in msg:
            # Try to compute from posted date
            if posted_date and data[entity]['posted']:
                posted = data[entity]['posted'][-1]
                match = re.search(r'came down (\d+) days later', msg)
                if match:
                    days = int(match.group(1))
                    try:
                        dt = datetime.strptime(posted, "%Y-%m-%d")
                        removed_dt = dt + timedelta(days=days)
                        data[entity]['removed'].append(removed_dt.strftime("%Y-%m-%d"))
                    except ValueError:
                        pass
        else:
            removed_date = extract_date_from_message(msg, removed_patterns)
            if removed_date:
                data[entity]['removed'].append(removed_date)
    return data

# ----------------------------------------------------------------------
# Fact extraction with conflict detection
# ----------------------------------------------------------------------

def get_fact_value(
    entity: str,
    doc_data: Union[Dict[str, List[str]], Dict[str, Dict[str, List[str]]]],
    fact_type: str = 'single'
) -> Tuple[Optional[str], Optional[str], str]:
    """
    Extract fact value from document data.
    Returns (value, document, status) where status is one of:
    - "ABSENT": no value found
    - "CONFLICT": multiple disagreeing values
    - "PRESENT": single value found
    """
    if fact_type == 'single':
        if entity not in doc_data:
            return None, None, "ABSENT"
        values = doc_data[entity]
        if not values:
            return None, None, "ABSENT"
        # Check for conflicts
        unique_values = set(values)
        if len(unique_values) > 1:
            return None, None, "CONFLICT"
        return values[0], "single", "PRESENT"
    elif fact_type == 'notice':
        if entity not in doc_data:
            return None, None, "ABSENT"
        posted = doc_data[entity].get('posted', [])
        removed = doc_data[entity].get('removed', [])
        if not posted and not removed:
            return None, None, "ABSENT"
        # For notice facts, we need to handle posted and removed separately
        # This function is called per fact (posted or removed)
        # So we need to know which fact we're extracting
        # We'll handle this in the calling code
        pass
    return None, None, "ABSENT"

def get_authorization_expiry(
    entity: str,
    work_auth_data: Dict[str, List[str]],
    ead_data: Dict[str, List[str]]
) -> Tuple[Optional[str], Optional[str], str]:
    """Get authorization expiry date according to rules."""
    # First try work_authorizations
    if entity in work_auth_data and work_auth_data[entity]:
        values = work_auth_data[entity]
        unique = set(values)
        if len(unique) > 1:
            return None, None, "CONFLICT"
        return values[0], "work_authorizations", "PRESENT"
    # Fallback to ead_cards
    if entity in ead_data and ead_data[entity]:
        values = ead_data[entity]
        unique = set(values)
        if len(unique) > 1:
            return None, None, "CONFLICT"
        return values[0], "ead_cards", "PRESENT"
    return None, None, "ABSENT"

def get_lca_filed(
    entity: str,
    lca_filing_data: Dict[str, List[str]],
    dol_receipt_data: Dict[str, List[str]]
) -> Tuple[Optional[str], Optional[str], str]:
    """Get LCA filed date according to rules."""
    # First try lca_filings
    if entity in lca_filing_data and lca_filing_data[entity]:
        values = lca_filing_data[entity]
        unique = set(values)
        if len(unique) > 1:
            return None, None, "CONFLICT"
        return values[0], "lca_filings", "PRESENT"
    # Fallback to dol_receipts
    if entity in dol_receipt_data and dol_receipt_data[entity]:
        values = dol_receipt_data[entity]
        unique = set(values)
        if len(unique) > 1:
            return None, None, "CONFLICT"
        return values[0], "dol_receipts", "PRESENT"
    return None, None, "ABSENT"

def get_notice_fact(
    entity: str,
    notice_data: Dict[str, Dict[str, List[str]]],
    fact_name: str
) -> Tuple[Optional[str], Optional[str], str]:
    """Get notice posted or removed date."""
    if entity not in notice_data:
        return None, None, "ABSENT"

    values = notice_data[entity].get(fact_name, [])
    if not values:
        return None, None, "ABSENT"

    unique = set(values)
    if len(unique) > 1:
        return None, None, "CONFLICT"

    return values[0], "lca_notices", "PRESENT"

# ----------------------------------------------------------------------
# Main program
# ----------------------------------------------------------------------

def main(directory: str) -> None:
    # Load all files
    file_data = {}
    for filename in [
        'dol_receipts.txt',
        'ead_cards.txt',
        'hr_roster.txt',  # Not used in rules but present
        'lca_filings.txt',
        'lca_notices.txt',
        'reverifications.txt',
        'work_authorizations.txt'
    ]:
        path = os.path.join(directory, filename)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                file_data[filename] = f.read()
        except FileNotFoundError:
            print(f"Warning: {filename} not found", file=sys.stderr)
            file_data[filename] = ""

    # Parse all documents
    dol_receipts = parse_dol_receipts(file_data.get('dol_receipts.txt', ''))
    ead_cards = parse_ead_cards(file_data.get('ead_cards.txt', ''))
    work_auth = parse_work_authorizations(file_data.get('work_authorizations.txt', ''))
    reverifications = parse_reverifications(file_data.get('reverifications.txt', ''))
    lca_filings = parse_lca_filings(file_data.get('lca_filings.txt', ''))
    lca_notices = parse_lca_notices(file_data.get('lca_notices.txt', ''))

    # Prepare result structure
    result = {}

    # Process all pairs
    entities = [f"E-410{i:02d}" for i in range(1, 17)]

    for rule in ['wf.reverify_window', 'wf.notice_posting']:
        for entity in entities:
            pair_id = f"{rule}::{entity}"
            result[pair_id] = {}

            if rule == 'wf.reverify_window':
                # Fact: authorization expiry
                expiry_val, expiry_doc, expiry_status = get_authorization_expiry(
                    entity, work_auth, ead_cards
                )
                if expiry_status == "PRESENT":
                    result[pair_id]["authorization expiry"] = [expiry_val, expiry_doc]
                elif expiry_status == "CONFLICT":
                    result[pair_id]["authorization expiry"] = "CONFLICT"
                else:
                    result[pair_id]["authorization expiry"] = "ABSENT"

                # Fact: reverification date
                rev_val, rev_doc, rev_status = get_fact_value(entity, reverifications, 'single')
                if rev_status == "PRESENT":
                    result[pair_id]["reverification date"] = [rev_val, "reverifications"]
                elif rev_status == "CONFLICT":
                    result[pair_id]["reverification date"] = "CONFLICT"
                else:
                    result[pair_id]["reverification date"] = "ABSENT"

            elif rule == 'wf.notice_posting':
                # Fact: notice posted
                posted_val, posted_doc, posted_status = get_notice_fact(entity, lca_notices, 'posted')
                if posted_status == "PRESENT":
                    result[pair_id]["notice posted"] = [posted_val, posted_doc]
                elif posted_status == "CONFLICT":
                    result[pair_id]["notice posted"] = "CONFLICT"
                else:
                    result[pair_id]["notice posted"] = "ABSENT"

                # Fact: notice removed
                removed_val, removed_doc, removed_status = get_notice_fact(entity, lca_notices, 'removed')
                if removed_status == "PRESENT":
                    result[pair_id]["notice removed"] = [removed_val, removed_doc]
                elif removed_status == "CONFLICT":
                    result[pair_id]["notice removed"] = "CONFLICT"
                else:
                    result[pair_id]["notice removed"] = "ABSENT"

                # Fact: LCA filed
                lca_val, lca_doc, lca_status = get_lca_filed(entity, lca_filings, dol_receipts)
                if lca_status == "PRESENT":
                    result[pair_id]["LCA filed"] = [lca_val, lca_doc]
                elif lca_status == "CONFLICT":
                    result[pair_id]["LCA filed"] = "CONFLICT"
                else:
                    result[pair_id]["LCA filed"] = "ABSENT"

    # Output JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>", file=sys.stderr)
        sys.exit(1)
    main(sys.argv[1])
